/* Components */
.btn, a.btn {
  display: inline-block;
  width: 100px;
  height: 36px;
  background-color: #c4c4c4;
  text-align: center;
  font-weight: 400;
  font-size: 14px;
  line-height: 36px;
  color: #fff;
  vertical-align: middle;
}

.btn:hover {
