}

.main-slider {
  display: none;
  position: relative;
  top: -1px;
  z-index: 20;
  overflow: hidden;
  width: 100%;
  background-color: #cbcbcb;
}

.main-slider ul {
  position: relative;
}

.main-slider ul li {
  display: table;
  width: 100%;
  height: 340px;
  background-position: 50% 50%;
  background-size: cover;
}

.main-slider ul li a {
  display: table;
  width: 100%;
  height: 100%;
  text-decoration: none;
  background-color: rgba(0, 0, 0, 0.15);
}

.main-slider ul li .inner {
  display: table-cell;
  vertical-align: middle;
}

.main-slider ul li .box {
  display: block;
  max-width: 910px;
  margin: 0 auto;
  padding: 0 24px 6px;
}

.main-slider ul li .text {
  display: block;
  overflow: hidden;
  max-width: 65%;
  text-overflow: ellipsis;
  font-weight: 300;
  font-size: 2.125em;
  line-height: 1.2352;
  color: #fff;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
}

.main-slider ul li .btn {
  display: block;
  width: 118px;
  height: 35px;
  margin-top: 32px;
  border-radius: 35px;
  line-height: 35px;
  background-color: #fff;
  color: #555;
}

.main-slider ul li .btn:hover {
  background-color: #04beb8;
  color: #fff;
}

.main-slider .prev,
.main-slider .next {
  display: none;
}

.main-slider .paging {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 10;
  margin-left: 447px;
  transform: translateY(-50%);
  -webkit-transform: translateY(-50%);
  -ms-transform: translateY(-50%);
}

.main-slider .paging button {
  display: block;
  width: 8px;
  height: 8px;
  margin: 10px 0;
  text-indent: -999em;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.4);
}

.main-slider .paging .current {
