  line-height: 6px;
  vertical-align: top;
}

.box-timeline-content {
  word-break: break-all;
}

/* ===== Cupertino (맥부킷) — 2026-08-27 =====
   정본: Blog-strategy/system/cupertino-design.md §10
   되돌리려면 이 블록만 통째로 지운다. */
body { background: #FFFFFF; }
/* ===== /Cupertino ===== */


/* ────────────────────────────────────────────────────────────
   2026-08-28 · 네이버 계열과 톤 맞추기
   네이버 dokyungja·doonablog 가 쓰는 문법을 그대로 옮겼다.
   ① 상단 브랜드 배너  ② 글 화면 상단 「전체보기」 목록
   ③ 커버 사진 제거 — 제목은 흰 바탕에 검정으로
   되돌리려면 이 블록을 통째로 지운다(원본: brand/skin-backup/).
   ──────────────────────────────────────────────────────────── */

/* ① 브랜드 배너 */
/* 배너는 HTML 이다(2026-08-28) — 이미지 한 장이면 배경색이 카테고리를 못 따라간다. */

/* ② 글 상단 목록 — 네이버의 「전체보기 N개의 글」 자리 */
.post-toplist { background:#fff; padding:0 24px; }
.post-toplist .inner { max-width:1080px; margin:0 auto; padding:30px 0 4px; }
.post-toplist .tl-head { font-size:15px; color:#6E6E73; margin:0 0 11px;
  font-family:"Pretendard-Regular","Apple SD Gothic Neo",sans-serif; }
.post-toplist .tl-head b { color:#1D1D1F; font-family:"Pretendard-SemiBold","Apple SD Gothic Neo",sans-serif; font-weight:400; }
.post-toplist ul { list-style:none; margin:0; padding:0; border-top:1px solid #E8E8ED; }
.post-toplist li { border-bottom:1px solid #E8E8ED; }
.post-toplist li a { display:flex; align-items:baseline; justify-content:space-between;
  gap:22px; padding:13px 2px; text-decoration:none; color:#1D1D1F;
  font-size:15px; font-family:"Pretendard-Regular","Apple SD Gothic Neo",sans-serif; }
.post-toplist li a:hover .t { text-decoration:underline; }
.post-toplist .t { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.post-toplist .d { flex:none; color:#8E8E93; font-size:13.5px; }

/* ③ 커버 사진을 걷어낸다 — 제목이 사진 위에서 안 읽혔다 */
/* ⚠️ 스킨 원본이 #tt-body-page .post-cover 를 absolute 로 띄운다 —
   그대로 두면 제목이 문서 흐름을 벗어나 목록 «위»로 올라간다(2026-08-28 실측).
   네이버 순서는 목록 → 카테고리 → 제목 → 작성자다. static 으로 되돌린다. */
.post-cover,
#tt-body-page .post-cover,
#tt-body-entry .post-cover { display:block; height:auto; background:#fff;
  position:static; top:auto; left:auto; }
.post-cover:before { display:none; }
.post-cover .inner { display:block; padding:46px 0 32px; }
.post-cover .category { color:#6E6E73; font-size:0.9375em; margin-bottom:15px; }
.post-cover h1 { font-family:"Pretendard-Bold","Apple SD Gothic Neo",sans-serif; font-weight:400; font-size:2.4em;
  line-height:1.32; letter-spacing:-0.03em; color:#141414; }
.post-cover .meta { color:#6E6E73; margin-top:24px; }
.post-cover .meta a { color:#6E6E73; }
.post-cover .meta a:before,
.post-cover .meta span:before { background-color:#C7C7CC; }

@media screen and (max-width:767px) {
  .post-cover .inner { padding:32px 0 24px; }
  .post-cover h1 { font-size:1.7em; }
  .post-toplist .inner { padding-top:22px; }
}

/* 글 제목은 «본문»이 맡는다(2026-08-28 사용자 결정) — 스킨 커버는 걷어냈다.
   여기 남는 건 카테고리·작성자·날짜 한 줄뿐이고, 목록 바로 아래에 온다. */
.post-byline { background:#fff; padding:0 24px; }
.post-byline .inner { max-width:1080px; margin:0 auto;
  padding:26px 0 6px; display:flex; align-items:baseline; gap:14px;
  font-family:"Pretendard-Regular","Apple SD Gothic Neo",sans-serif; }
.post-byline .category { font-size:0.9375em; color:#6E6E73; }
.post-byline .meta { font-size:0.875em; color:#8E8E93; }
.post-byline .meta a { color:#8E8E93; }
.post-byline .meta a:before,
.post-byline .meta span:before { content:""; display:inline-block; width:2px; height:2px;
  margin:0 8px 0 4px; background-color:#C7C7CC; vertical-align:middle; }
.post-byline .meta span:first-child:before { content:none; }

/* ── 2026-08-28 · 좌우까지 «통으로» 일체화 ─────────────────────
   네이버는 배너 → 메뉴(카테고리 포함) → 본문이 하나의 폭 안에서 이어진다.
   사이드바를 없애고 카테고리를 상단 바로 올려 그 구조를 맞춘다.
   되돌리려면 이 블록만 지운다. */
@media screen and (min-width:768px) {
  /* 배너가 브랜드 역할을 하므로 위 로고·검색 줄은 걷어낸다 */
  #header .blog-header,
  #header .util { display:none; }
  #header { border-bottom:0; }
  #header .inner { padding:0; }

  /* 전체 폭으로 흐르던 선을 배너 폭 안으로 */
  #gnb { max-width:1080px; margin:0 auto; }

  /* 카테고리를 가로 바로 — 사이드바 자리를 대신한다 */
  .cat-bar { max-width:1080px; margin:0 auto; border-bottom:1px solid #E8E8ED; }
  .cat-bar ul { display:flex; flex-wrap:wrap; gap:26px; list-style:none;
    margin:0; padding:0 0 14px; }
  .cat-bar li { margin:0; }
  .cat-bar a { font-family:"Pretendard-Regular","Apple SD Gothic Neo",sans-serif;
    font-size:15px; color:#1D1D1F; text-decoration:none; }
  .cat-bar a:hover { text-decoration:underline; }
  .cat-bar ul ul { padding:0; gap:18px; }
  .cat-bar ul ul a { font-size:14px; color:#6E6E73; }

  /* 사이드바를 접고 본문이 폭을 다 쓴다 */
  #aside { display:none; }
  #content { width:100%; max-width:none; float:none; }
}

/* 바깥은 회색, 콘텐츠는 흰 카드 — 네이버의 «통 일체형» 뼈대다.
   --unify-card */
@media screen and (min-width:768px) {
  html, body { background:#F1F1F1; }
  #wrap { max-width:1000px; margin:0 auto; background:#FFFFFF;
    box-shadow:none; }
  #header, #container { background:#FFFFFF; }
  .brand-banner, #gnb, .cat-bar,
  .post-toplist .inner, .post-byline .inner,
  .content-wrap { max-width:900px; }
  .content-wrap { padding-left:0; padding-right:0; }
}

/* 일체화 마무리 — --unify-tidy */
@media screen and (min-width:768px) {
  /* 사이드바를 감췄으니 그 구분선(.content-wrap::before)도 없앤다 */
  .content-wrap:before { display:none; }
  .content-wrap:after { width:auto; }

  /* 카테고리를 «한 줄»로. 티스토리 마크업은 ul > li > ul 로 한 겹 더 들어간다 */
  .cat-bar .tt_category,
  .cat-bar .tt_category > li,
  .cat-bar .tt_category ul { display:flex; flex-wrap:wrap; align-items:baseline;
    gap:24px; margin:0; padding:0; list-style:none; }
  .cat-bar .tt_category > li { gap:24px; }
  .cat-bar .tt_category .c_cnt,
  .cat-bar .tt_category .category_rss,
  .cat-bar .tt_category img { display:none; }

  /* 배너 위·아래 숨통 */
  #wrap { padding-bottom:8px; }
  .brand-banner { margin-top:14px; }
  .cat-bar { padding-bottom:14px; }
  .post-toplist .inner { padding-top:26px; }
}

/* 본문 바탕은 «크림»이다 — claude-design.md 정본(크림 바탕·클레이 액센트).
   순백 위에 올리면 조판의 색이 죽는다. 스킨은 카테고리를 모르므로
   toplist.js 가 body 에 붙여 주는 cat-* 클래스로 가른다. --unify-paper */
@media screen and (min-width:768px) {
  #content .entry-content { width:900px; max-width:900px; margin:0 auto;
    padding:40px 44px 56px; box-sizing:border-box; }
  /* Claude code — 크림 */
  body.cat-claude-code #content .entry-content { background:#FAF9F5; }
  /* Apple & Mac · IT news — 흰 바탕(cupertino) */
  body.cat-apple-mac #content .entry-content,
  body.cat-it-news #content .entry-content { background:#F5F5F7; }
}

/* ── 카드 «전체»를 카테고리 색으로 ─────────────────────────────
   본문만 칠하면 배너·메뉴·목록이 흰색으로 남아 층이 진다(2026-08-28 지적).
   toplist.js 가 body 에 붙이는 cat-* 로 #wrap 을 통째로 칠한다. --unify-fill */
@media screen and (min-width:768px) {
  #wrap,
  #header, #container, .content-wrap, #content,
  .post-toplist, .post-byline { background:transparent; }
  #wrap { background:#F5F5F7; }                     /* 기본 = 애플 그레이 */
  body.cat-claude-code #wrap { background:#FAF9F5; } /* Claude code = 크림 */
  body.cat-apple-mac #wrap,
  body.cat-it-news  #wrap { background:#F5F5F7; }
  /* 본문 개별 배경은 이제 필요 없다 — 카드색을 그대로 물려받는다 */
  body.cat-claude-code #content .entry-content,
  body.cat-apple-mac #content .entry-content,
  body.cat-it-news #content .entry-content { background:transparent; }

  /* 배너 — HTML. 배경을 안 깔아야 카드색이 그대로 비친다 */
  .brand-banner { display:flex; align-items:center; justify-content:flex-start;
    gap:44px; max-width:900px; margin:0 auto; padding:22px 0 18px;
    text-decoration:none; border-bottom:6px solid #141414; }
  .bb-txt { display:block; }
  .bb-badge { display:inline-block; background:#E3ECF7; color:#0066CC;
    font-family:"Pretendard-ExtraBold","Apple SD Gothic Neo",sans-serif;
    font-size:15px; line-height:1; padding:7px 15px; border-radius:999px;
    margin-bottom:14px; }
  .bb-title { display:block;
    font-family:"Pretendard-Black","Apple SD Gothic Neo",sans-serif;
    font-size:42px; line-height:1.2; letter-spacing:-.035em; color:#141414; }
  .bb-sub { display:block; margin-top:13px; font-size:16px; color:#3A3A3C;
    letter-spacing:-.012em;
    font-family:"Pretendard-ExtraBold","Apple SD Gothic Neo",sans-serif; }
  .bb-sub b { color:#0066CC; font-weight:inherit; }
  .bb-art { flex:none; height:150px; width:auto; display:block; margin-right:4px; }
}
@media screen and (max-width:767px) {
  .brand-banner { display:block; padding:18px 20px; text-decoration:none;
    border-bottom:5px solid #141414; }
  .bb-title { display:block; font-size:26px; line-height:1.24; color:#141414;
    font-family:"Pretendard-Black","Apple SD Gothic Neo",sans-serif; }
  .bb-badge { display:inline-block; background:#E3ECF7; color:#0066CC;
    font-size:13px; padding:5px 12px; border-radius:999px; margin-bottom:10px; }
  .bb-sub { display:block; margin-top:10px; font-size:13px; color:#3A3A3C; }
  .bb-art { display:none; }
}

/* 사이드 레일 자리 — 애드센스 자동광고(사이드 레일)는 카드 «바깥» 여백에 뜬다.
   카드가 넓으면 뜰 자리가 없고, 너무 좁으면 본문이 답답하다.
   레일 1개(160px) + 숨통(24px) = 한쪽 184px 를 남긴다. --unify-rail
   ⚠️ 티스토리가 금지한 건 앵커(2025-06-01)·전면광고(2025-09-03)다. 레일은 허용. */
@media screen and (min-width:1400px) {
  #wrap { max-width:1000px; }
}
@media screen and (min-width:768px) and (max-width:1399px) {
  #wrap { max-width:calc(100vw - 96px); }
}

/* 상단부를 조인다 — 메뉴·카테고리·목록 사이 빈 자리가 너무 넓었다.
   ⚠️ 72px 공백의 정체는 #content 의 padding-top 이다(커버가 absolute 였던 시절의
      자리 확보). 커버를 없앤 지금은 필요 없다. --unify-tight */
@media screen and (min-width:768px) {
  #content { padding-top:0; }
  #gnb ul { padding:0; }
  #gnb li { padding:0 22px 0 0; }
  #gnb a { font-size:14px; }
  .cat-bar { padding-bottom:11px; }
  .cat-bar .tt_category,
  .cat-bar .tt_category > li,
  .cat-bar .tt_category ul { gap:20px; }
  .cat-bar a { font-size:14px; }
  .post-toplist .inner { padding:20px 0 2px; }
  .post-toplist .tl-head { font-size:13.5px; margin-bottom:8px; }
  .post-toplist li a { padding:9px 2px; font-size:14px; }
  .post-toplist .d { font-size:12.5px; }
  .post-byline .inner { padding:18px 0 4px; }
}

/* 사이드 레일 — 카드 «바깥» 여백에만. 콘텐츠를 절대 덮지 않는다. --unify-railad
   카드 1000 → 반폭 500. 그 밖으로 28px 띄우고 160px 레일을 세운다.
   1440px 미만에서는 자리가 없으므로 아예 감춘다(JS 도 요청하지 않는다). */
.rail-ad { display:none; }
@media screen and (min-width:1440px) {
  .rail-ad { display:block; position:fixed; top:50%; transform:translateY(-50%);
    width:160px; z-index:5; }
  .rail-left  { left:calc(50% - 500px - 28px - 160px); }
  .rail-right { right:calc(50% - 500px - 28px - 160px); }
}


/* ═══════════════════════════════════════════════════════════
   본문 폭 네이버 정렬 + 목록 통일 — 2026-08-28
   되돌리기: 이 블록만 통째로 삭제
   직전 백업: macbookit-tistory/brand/skin-backup/style-PRE-width-20260828-195634.css

   실측(1600px 창): 네이버 블로그 컨테이너 787 · 글줄 707
   ⚠️ 특이도 주의 — 아래 두 규칙이 기본값을 쥐고 있어서 반드시 같은 무게로 덮어야 한다.
      · #content .entry-content { width:900px }            ← ID 라 (1,0,1,0)
      · .list-type-vertical .post-item .thum { padding-bottom:130.43% }  ← (0,0,3,0)
      낮은 특이도로 쓰면 조용히 안 먹는다(2026-08-28 실제로 한 번 밟았다).
   .entry-content 는 box-sizing:border-box + 좌우 패딩 44px → 707+88 = 795px.
   ═══════════════════════════════════════════════════════════ */
@media screen and (min-width: 768px) {
  #content .entry-content { width: 795px; max-width: 795px; }
  .post-byline .inner, .post-toplist .inner { max-width: 795px; }
  #content .entry-content img,
  #content .entry-content figure,
  #content .entry-content table,
  #content .entry-content pre { max-width: 100%; }
  #content .entry-content table { display: block; overflow-x: auto; width: 100%; }
}

/* 목록 카드 — 두 블로그 동일 규격. --unify-list
   130.43%(=1:1.3 세로) 는 카드 한 장이 화면 절반을 먹는다. 4:3 으로 낮춘다.
   기본 스킨의 translateY 는 세로 카드에서 제목을 잘라 먹어 object-fit 으로 바꾼다. */
.post-item .thum,
.list-type-vertical .post-item .thum {
  padding-bottom: 75%;
  margin-bottom: 12px;
  border-radius: 10px;
  background-color: #F1F1F1;
}
.post-item .thum img,
.list-type-vertical .post-item .thum img {
  position: absolute; top: 0; left: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  transform: none; -webkit-transform: none;
}
.post-item .excerpt,
.list-type-vertical .post-item .excerpt { display: none; }
.post-item .title { font-size: 15px; line-height: 1.45; margin-bottom: 6px; }
.post-item .meta { font-size: 12.5px; }
.post-item { margin-bottom: 40px; }
@media screen and (max-width: 767px) {
  .post-item .thum,
  .list-type-vertical .post-item .thum { padding-bottom: 62%; }
  .post-item .title { font-size: 14.5px; }
}


/* ═══════════════════════════════════════════════════════════
   목록을 «색인» 형태로 — press.playw.work/trend 조판.  --unify-index
   되돌리기: 이 블록만 지우면 직전의 카드 목록으로 돌아간다.

   왜: 카드 목록은 글마다 카드 이미지를 만들어야 하고, 그 카드가 검색 포털의
       대표이미지까지 차지한다. 색인형은 목록에 이미지가 필요 없어서,
       대표이미지 자리를 «본문 히어로»에 넘겨줄 수 있다(hero_thumb.py).
   구조: 티스토리 마크업 a > .thum + .title + .excerpt + .meta 를
        flex + order 로 «날짜 | 제목» 한 줄로 다시 세운다.
   ⚠️ .excerpt 는 숨긴다 — 본문 첫 요소가 제목 h1 이라(스킨이 제목을 안 그려서
      넣은 것) 발췌문이 «제목+제목+요약» 으로 시작한다(2026-08-28 실측).
   ⚠️ !important 를 쓰는 이유: 스킨 원본이 .list-type-thumbnail .post-item .thum
      처럼 (0,0,3,0) 으로 잡아 놔서 .post-item .thum (0,0,2,0) 이 그냥 진다.
   ═══════════════════════════════════════════════════════════ */
.post-item .thum,
.post-item .excerpt { display: none !important; }

@media screen and (min-width: 768px) {
  .post-item {
    float: none !important;
    width: 100% !important;
    margin: 0 !important;
    border-bottom: 1px solid #E8E8ED;
  }
  .post-item:first-child { border-top: 1px solid #E8E8ED; }
  .post-item a {
    display: flex !important;
    align-items: baseline;
    gap: 26px;
    padding: 18px 2px !important;
  }
  .post-item .meta {
    order: 1 !important;
    flex: 0 0 96px;
    margin: 0 !important;
    font-size: 13px;
    color: #86868B;
    white-space: nowrap;
  }
  .post-item .meta span:before { display: none !important; }
  .post-item .title {
    order: 2 !important;
    flex: 1 1 auto;
    min-width: 0;
    margin: 0 !important;
    font-size: 16px !important;
    line-height: 1.5 !important;
    color: #1D1D1F;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .post-item a:hover .title { text-decoration: underline; }
}

@media screen and (max-width: 767px) {
  .post-item {
    float: none !important;
    width: 100% !important;
    margin: 0 !important;
    border-bottom: 1px solid #E8E8ED;
  }
  .post-item a { display: block !important; padding: 15px 0 !important; }
  .post-item .title {
    display: block; font-size: 15px !important; line-height: 1.5 !important;
    white-space: normal; margin: 0 0 5px !important;
  }
  .post-item .meta { font-size: 12.5px; color: #86868B; }
}


/* ═══════════════════════════════════════════════════════════
   머리말·목록 가로 정렬 + 상하 리듬.  --unify-align --unify-rhythm  (2026-08-28)
   되돌리기: 이 블록만 통째로 지운다.

   ── 왜 (1647px 창 실측) ─────────────────────────────────────
   네이버 폭 맞추기에서 본문·바이라인·상단목록만 795 로 줄이고 «머리말 3형제»를
   900 인 채로 뒀다. 그래서
     브랜드배너 / #gnb / .cat-bar   x=373 · w=900
     본문·목록·「전체 글 N」        x=343 · w=960
   왼쪽 시작선이 30px 어긋났다. 글 화면에서도 배너만 혼자 넓었다.

   세로도 같이 어긋나 있었다.
     #gnb 아래 «현재 위치» 검은 표식이 아래 여백 24px 라 메뉴에서 떨어져 나와
       분류 줄 위에 «떠 있는 점»처럼 보였다
     분류 줄 위 여백 0 · 「전체 글 N」 위 4 / 아래 18 — 어느 쪽에도 안 붙었다
   목록을 색인형(--unify-index)으로 바꾸면서 행이 71px 로 얇아져 더 도드라졌다.

   ── 어떻게 ─────────────────────────────────────────────────
   가로: 전부 795 로 맞춘다. 795 는 이미 정해진 종이 폭이다(707 글줄 + 패딩 44).
        #content 는 폭만 잡혀 있고 가운데 정렬이 없어서 margin auto 를 같이 준다.
   세로: 표식이 «글자에 붙게» 메뉴 아래 여백 24 → 10, 대신 분류 줄에 위 16.
        「전체 글 N」은 26/12 로 목록의 머리가 되게 한다.
   ⚠️ #gnb 는 height:66px 고정이라 안쪽 여백만 줄이면 높이가 안 준다 → height:auto.
   ⚠️ #gnb 안쪽은 ul margin-left:-30 + li padding 26 + a padding 4 로 «첫 글자»가
      #gnb 왼쪽 끝에 오게 맞춰져 있다. #gnb 만 옮기면 글자도 따라온다.
   ═══════════════════════════════════════════════════════════ */
@media screen and (min-width: 768px) {
  .brand-banner,
  #gnb,
  .cat-bar { max-width: 795px !important; }

  #content {
    max-width: 795px !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }

  #gnb { height: auto !important; }
  #gnb ul li a { padding: 20px 4px 10px !important; }

  .cat-bar { padding-top: 16px !important; padding-bottom: 14px !important; }

  .post-header { padding: 26px 0 12px !important; }
}


/* ═══════════════════════════════════════════════════════════
   푸터 크레딧 — 가운데 모노그램.  --unify-credit   (2026-08-28)
   되돌리기: 이 블록 + 스킨 HTML 의 .site-credit 묶음을 함께 지운다.

   왜: 스킨 기본 푸터는 「Designed by 티스토리 / © Daum Corp.」 두 줄이
       왼쪽에 흘려져 있었다. 글자만 갈아 끼우면 여전히 «남은 자리»처럼 보인다.
       가운데로 모으고 얇은 선 사이에 모노그램을 세워 마무리 표시로 만든다.
   ⚠️ 이미지를 쓰지 않는다. 네 블로그가 팔레트가 서로 다르고(맥부킷 쿠퍼티노,
      경자씨 계열 종이), 푸터 한 줄에 CDN 요청을 붙일 이유가 없다.
   ⚠️ .copyright(© Daum Corp.)는 스킨 라이선스(MIT) 고지라 지우지 않는다.
      대신 글자를 한 단계 더 작게·연하게 해서 크레딧에 종속시킨다.
   ═══════════════════════════════════════════════════════════ */
#footer .site-credit {
  display: flex; align-items: center; justify-content: center;
  gap: 14px; margin: 0 0 14px;
}
#footer .sc-rule { display: block; width: 44px; height: 1px; background: #DFDFDF; }
#footer .sc-mark {
  display: grid; place-items: center;
  width: 26px; height: 26px; border-radius: 8px;
  background: #1D1D1F; color: #fff;
  font-size: 12px; font-weight: 700; line-height: 1; letter-spacing: 0;
}
#footer .sc-text {
  text-align: center; font-size: 12px; letter-spacing: .06em;
  color: #86868B; margin: 0 0 4px;
}
#footer .sc-text b { color: #1D1D1F; font-weight: 600; }
#footer .copyright { text-align: center; font-size: 11px; color: #B9B9B9; margin: 0; }
